package com.bank.rsocket.edge;

import com.bank.rsocket.dto.BalanceResponse;
import com.bank.rsocket.function.BalanceFunction;
import lombok.extern.slf4j.Slf4j;
import org.springframework.messaging.handler.annotation.MessageMapping;
import org.springframework.stereotype.Controller;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;
import java.math.BigDecimal;
import java.time.Duration;

// ALWAYS-ON server (runs in a container/K8s, NOT in a function).
// It owns the persistent RSocket connections and streaming.
@Slf4j
@Controller
public class EdgeRSocketServer {
    private final BalanceFunction balanceFunction = new BalanceFunction();

    // STREAMING lives here, on the always-on tier — never inside a function.
    @MessageMapping("price.stream")
    public Flux<String> priceStream(String symbol) {
        log.info("Edge holds long-lived stream for {}", symbol);
        return Flux.interval(Duration.ofMillis(200))
            .map(seq -> symbol + " Rs." + (2450 + seq)).take(5);
    }

    // SHORT request-response → delegate to a stateless serverless-style handler.
    @MessageMapping("account.balance")
    public Mono<BalanceResponse> balance(String accountId) {
        log.info("Edge delegates short compute to BalanceFunction for {}", accountId);
        // In production this would be an async Lambda invoke; shown inline here.
        return Mono.fromCallable(() -> balanceFunction.handle(accountId));
    }
}
