package com.bank.rsocket.function;

import com.bank.rsocket.dto.BalanceResponse;
import lombok.extern.slf4j.Slf4j;
import java.math.BigDecimal;

// STATELESS, short-lived handler — the serverless unit of work.
// No connection state, no streams; completes well within the timeout.
@Slf4j
public class BalanceFunction {
    public BalanceResponse handle(String accountId) {
        log.info("Serverless compute balance for {}", accountId);
        BigDecimal bal = "SAV2001".equals(accountId)
            ? new BigDecimal("1000000") : new BigDecimal("250000");
        return new BalanceResponse(accountId, bal);
    }
}
